def find_8connected_components_per_value(grid_out):
    h, w = len(grid_out), len(grid_out[0])
    visited = [[False]*w for _ in range(h)]
    components = {}

    for v in sorted(set(row[r] for row in grid_out for r in range(len(row)))):
        if v == 0:
            continue

        for i in range(h):
            for j in range(w):
                if grid_out[i][j] == v and not visited[i][j]:
                    comp = [(i,j)]
                    visited[i][j] = True

                    stack = [(i,j)]
                    while stack:
                        r, c = stack.pop()
                        for dr in [-1, 0, 1]:
                            for dc in [-1, 0, 1]:
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid_out[nr][nc] == v:
                                    visited[nr][nc] = True
                                    comp.append((nr, nc))
                                    stack.append((nr, nc))

                    if v not in components or len(comp) > len(components[v]):
                        components[v] = comp

    return components

